-- =============================================================================
-- Innopixel - database schema (PostgreSQL 15+)
--
-- Run against an empty database:
--   psql -h localhost -U postgres -d innopixel -f database/001_create_schema.sql
--
-- Conventions (the backend's SQL depends on them):
--   * Table and column names are lowercase. Foreign keys are named <table>_id.
--   * "user", "create", "read", "update", "delete" and "date" are reserved words
--     in PostgreSQL and must be quoted.
--   * Ids are generated by the database (GENERATED ALWAYS AS IDENTITY).
--   * All points in time are TIMESTAMPTZ (stored as UTC). Plain dates use DATE.
--   * Foreign keys use the default NO ACTION. The backend itself removes rows that
--     depend on a deleted row (link tables etc.) in the same SQL statement.
--
-- Changes compared to the original proposal:
--   * ADMIN and CLIENT no longer use INHERITS. PostgreSQL inheritance does not carry
--     the primary key over to the child tables, and a foreign key to "user" does not
--     recognise rows in the child tables (e.g. WORKLOGLIST.USER_ID would reject an
--     admin). Instead, admin.id and client.id are both the primary key and a foreign
--     key to "user".id: an admin IS a user with the same id.
--   * "user" has an EMAIL column (used by getUserByEmail/updateUserByEmail).
--   * PROGRESS.CHANGEDAT is TIMESTAMPTZ, SYSTEMLOG.CHANGEDLOCATIONSYSTEM is VARCHAR
--     (it names the part of the system that changed).
--   * Link tables have UNIQUE constraints so the same link cannot exist twice.
--   * New tables for modules that were not in the proposal: page (Pages, SEO),
--     image (Images), aisuggestion (ChatbotInterpreter), chatsession and
--     chatmessage (ChatbotSystem).
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- User module: the parts a user consists of
-- -----------------------------------------------------------------------------

CREATE TABLE location (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    postalcode  VARCHAR(20)  NOT NULL,
    city        VARCHAR(100) NOT NULL,
    region      VARCHAR(100) NOT NULL,
    country     VARCHAR(100) NOT NULL
);

CREATE TABLE name (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    firstname   VARCHAR(100) NOT NULL,
    middlename  VARCHAR(100),
    lastname    VARCHAR(100) NOT NULL
);

CREATE TABLE address (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    streetname  VARCHAR(200) NOT NULL,
    housenumber VARCHAR(20)  NOT NULL
);

CREATE TABLE telephone (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    countrycode INTEGER NOT NULL CHECK (countrycode > 0),
    phonenumber BIGINT  NOT NULL CHECK (phonenumber > 0)
);

-- Three separate values, as in the original proposal.
CREATE TABLE birth (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    birthday    TIMESTAMPTZ NOT NULL,
    birthmonth  TIMESTAMPTZ NOT NULL,
    birthyear   TIMESTAMPTZ NOT NULL
);

-- -----------------------------------------------------------------------------
-- User module: users, clients, contacts, messages, admins and rights
-- -----------------------------------------------------------------------------

-- Soft delete: a user is deleted when deleted_at is set.
CREATE TABLE "user" (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email        VARCHAR(254),
    deleted_at   TIMESTAMPTZ,
    location_id  INTEGER REFERENCES location (id),
    name_id      INTEGER NOT NULL REFERENCES name (id),
    address_id   INTEGER NOT NULL REFERENCES address (id),
    telephone_id INTEGER NOT NULL REFERENCES telephone (id),
    birth_id     INTEGER NOT NULL REFERENCES birth (id)
);

-- Two active users cannot share an email address. Deleted users do not count.
CREATE UNIQUE INDEX user_email_active_key ON "user" (email) WHERE deleted_at IS NULL AND email IS NOT NULL;
CREATE INDEX user_location_id_idx ON "user" (location_id);

-- A client IS a user (same id).
CREATE TABLE client (
    id INTEGER PRIMARY KEY REFERENCES "user" (id)
);

-- Inquiries from the contact form (US-10) and from the chatbot.
CREATE TABLE contact (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    fullname     VARCHAR(200) NOT NULL,
    email        VARCHAR(254) NOT NULL,
    address      VARCHAR(300),
    registration VARCHAR(100),
    client_id    INTEGER REFERENCES client (id)
);

CREATE INDEX contact_client_id_idx ON contact (client_id);
CREATE INDEX contact_email_idx ON contact (email);

-- "disabled" marks an inquiry as handled/archived.
CREATE TABLE message (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    disabled    BOOLEAN       NOT NULL DEFAULT false,
    description VARCHAR(5000) NOT NULL,
    sendtime    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    contact_id  INTEGER REFERENCES contact (id)
);

CREATE INDEX message_contact_id_idx ON message (contact_id, sendtime DESC);

-- An admin IS a user (same id).
CREATE TABLE admin (
    id         INTEGER PRIMARY KEY REFERENCES "user" (id),
    message_id INTEGER REFERENCES message (id)
);

CREATE INDEX admin_message_id_idx ON admin (message_id);

CREATE TABLE rights (
    id       INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "create" BOOLEAN NOT NULL DEFAULT false,
    "read"   BOOLEAN NOT NULL DEFAULT false,
    "update" BOOLEAN NOT NULL DEFAULT false,
    "delete" BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE rightslist (
    id        INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    admin_id  INTEGER NOT NULL REFERENCES admin (id),
    rights_id INTEGER NOT NULL REFERENCES rights (id),
    UNIQUE (admin_id, rights_id)
);

CREATE INDEX rightslist_rights_id_idx ON rightslist (rights_id);

-- -----------------------------------------------------------------------------
-- User module: work logs
-- -----------------------------------------------------------------------------

CREATE TABLE worklog (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    description VARCHAR(2000),
    "date"      DATE        NOT NULL,
    checkin     TIMESTAMPTZ NOT NULL,
    checkout    TIMESTAMPTZ,
    CHECK (checkout IS NULL OR checkout >= checkin)
);

CREATE TABLE workloglist (
    id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    worklog_id INTEGER NOT NULL REFERENCES worklog (id),
    user_id    INTEGER NOT NULL REFERENCES "user" (id),
    UNIQUE (worklog_id, user_id)
);

CREATE INDEX workloglist_user_id_idx ON workloglist (user_id);

-- -----------------------------------------------------------------------------
-- Projects module: services and their texts in several languages
-- -----------------------------------------------------------------------------

CREATE TABLE services (
    id                 INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    projectdescription VARCHAR(2000) NOT NULL,
    iconidentifier     VARCHAR(100)
);

-- Which rights apply to which services (owned by the User module).
CREATE TABLE servicelist (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    rights_id   INTEGER NOT NULL REFERENCES rights (id),
    services_id INTEGER NOT NULL REFERENCES services (id),
    UNIQUE (rights_id, services_id)
);

CREATE INDEX servicelist_services_id_idx ON servicelist (services_id);

CREATE TABLE languages (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    description  VARCHAR(200),
    languagetype VARCHAR(5)     NOT NULL CHECK (languagetype IN ('da', 'en')),
    text         VARCHAR(10000) NOT NULL
);

CREATE TABLE languagelist (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    services_id  INTEGER NOT NULL REFERENCES services (id),
    languages_id INTEGER NOT NULL REFERENCES languages (id),
    UNIQUE (services_id, languages_id)
);

CREATE INDEX languagelist_languages_id_idx ON languagelist (languages_id);

-- -----------------------------------------------------------------------------
-- Projects module: projects, progress, categories and technologies
-- -----------------------------------------------------------------------------

CREATE TABLE category (
    id   INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE technology (
    id   INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE
);

-- currentstatus controls whether the project is shown and indexed (US-17, US-19).
-- progress_id gets its foreign key below, because progress also points back at projects.
CREATE TABLE projects (
    id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name          VARCHAR(200)   NOT NULL,
    description   VARCHAR(10000),
    deadline      TIMESTAMPTZ,
    currentstatus VARCHAR(20)    NOT NULL DEFAULT 'Draft' CHECK (currentstatus IN ('Draft', 'Published')),
    progress_id   INTEGER
);

CREATE INDEX projects_currentstatus_idx ON projects (currentstatus);

CREATE TABLE progress (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name        VARCHAR(200) NOT NULL,
    comment     VARCHAR(2000),
    changedat   TIMESTAMPTZ,
    changedby   VARCHAR(200),
    projects_id INTEGER REFERENCES projects (id)
);

CREATE INDEX progress_projects_id_idx ON progress (projects_id);

ALTER TABLE projects
    ADD CONSTRAINT projects_progress_id_fkey FOREIGN KEY (progress_id) REFERENCES progress (id);

CREATE TABLE projectlist (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    projects_id INTEGER NOT NULL REFERENCES projects (id),
    services_id INTEGER NOT NULL REFERENCES services (id),
    UNIQUE (projects_id, services_id)
);

CREATE INDEX projectlist_services_id_idx ON projectlist (services_id);

CREATE TABLE clientlist (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    client_id   INTEGER NOT NULL REFERENCES client (id),
    projects_id INTEGER NOT NULL REFERENCES projects (id),
    UNIQUE (client_id, projects_id)
);

CREATE INDEX clientlist_projects_id_idx ON clientlist (projects_id);

CREATE TABLE categorylist (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    is_primary  BOOLEAN NOT NULL DEFAULT false,
    projects_id INTEGER NOT NULL REFERENCES projects (id),
    category_id INTEGER NOT NULL REFERENCES category (id),
    UNIQUE (projects_id, category_id)
);

CREATE INDEX categorylist_category_id_idx ON categorylist (category_id);

-- A project has at most one primary category.
CREATE UNIQUE INDEX categorylist_one_primary_key ON categorylist (projects_id) WHERE is_primary;

CREATE TABLE technologylist (
    id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    projects_id   INTEGER NOT NULL REFERENCES projects (id),
    technology_id INTEGER NOT NULL REFERENCES technology (id),
    UNIQUE (projects_id, technology_id)
);

CREATE INDEX technologylist_technology_id_idx ON technologylist (technology_id);

-- -----------------------------------------------------------------------------
-- Statistics module
-- -----------------------------------------------------------------------------

CREATE TABLE systemlog (
    id                    INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    description           VARCHAR(2000) NOT NULL,
    timezonestamp         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    changedlocationsystem VARCHAR(100)
);

CREATE INDEX systemlog_timezonestamp_idx ON systemlog (timezonestamp);
CREATE INDEX systemlog_changedlocationsystem_idx ON systemlog (changedlocationsystem, timezonestamp DESC);

-- -----------------------------------------------------------------------------
-- Pages module: public pages with SEO information (US-03, US-19)
-- -----------------------------------------------------------------------------

CREATE TABLE page (
    id              INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    slug            VARCHAR(200) NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*$'),
    languagetype    VARCHAR(5)   NOT NULL CHECK (languagetype IN ('da', 'en')),
    title           VARCHAR(200) NOT NULL,
    content         TEXT,
    seotitle        VARCHAR(70),
    metadescription VARCHAR(160),
    is_published    BOOLEAN      NOT NULL DEFAULT false,
    is_indexable    BOOLEAN      NOT NULL DEFAULT true,
    updated_at      TIMESTAMPTZ,
    UNIQUE (slug, languagetype)
);

-- -----------------------------------------------------------------------------
-- Images module: project images (US-07)
-- -----------------------------------------------------------------------------

CREATE TABLE image (
    id               INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    projects_id      INTEGER      NOT NULL REFERENCES projects (id),
    filename         VARCHAR(100) NOT NULL UNIQUE,
    originalfilename VARCHAR(255),
    contenttype      VARCHAR(50)  NOT NULL CHECK (contenttype IN ('image/jpeg', 'image/png', 'image/webp')),
    sizebytes        BIGINT       NOT NULL CHECK (sizebytes > 0),
    alttext          VARCHAR(300),
    sortorder        INTEGER      NOT NULL DEFAULT 0,
    uploaded_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX image_projects_id_idx ON image (projects_id, sortorder);

-- -----------------------------------------------------------------------------
-- ChatbotInterpreter module: AI suggestions that an admin approves (US-21)
-- -----------------------------------------------------------------------------

-- accepted: NULL = not handled yet, true = approved, false = rejected.
CREATE TABLE aisuggestion (
    id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    type          VARCHAR(30) NOT NULL CHECK (type IN ('SeoTitle', 'MetaDescription', 'ProjectDescription')),
    originaltext  TEXT,
    suggestedtext TEXT        NOT NULL,
    accepted      BOOLEAN,
    createdat     TIMESTAMPTZ NOT NULL DEFAULT now(),
    projects_id   INTEGER     NOT NULL REFERENCES projects (id)
);

CREATE INDEX aisuggestion_projects_id_idx ON aisuggestion (projects_id, createdat DESC);
CREATE INDEX aisuggestion_pending_idx ON aisuggestion (createdat DESC) WHERE accepted IS NULL;

-- -----------------------------------------------------------------------------
-- ChatbotSystem module: chat sessions and their messages
-- -----------------------------------------------------------------------------

-- token is the session's secret key. Visitors only ever reach their chat through it,
-- so chats cannot be read by guessing the sequential id.
-- contact_id is set when the chat has been turned into an inquiry.
CREATE TABLE chatsession (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    token        UUID        NOT NULL UNIQUE,
    startedat    TIMESTAMPTZ NOT NULL DEFAULT now(),
    endedat      TIMESTAMPTZ,
    status       VARCHAR(30) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Ended', 'ConvertedToContact')),
    languagetype VARCHAR(5)  NOT NULL CHECK (languagetype IN ('da', 'en')),
    contact_id   INTEGER REFERENCES contact (id)
);

CREATE INDEX chatsession_startedat_idx ON chatsession (startedat);
CREATE INDEX chatsession_contact_id_idx ON chatsession (contact_id);

-- intent is what the interpreter recognised in the visitor's message (NULL for the bot's answers).
CREATE TABLE chatmessage (
    id             INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sender         VARCHAR(10) NOT NULL CHECK (sender IN ('User', 'Bot')),
    text           TEXT        NOT NULL,
    sendtime       TIMESTAMPTZ NOT NULL DEFAULT now(),
    intent         VARCHAR(50),
    chatsession_id INTEGER     NOT NULL REFERENCES chatsession (id)
);

CREATE INDEX chatmessage_chatsession_id_idx ON chatmessage (chatsession_id, sendtime, id);
CREATE INDEX chatmessage_intent_idx ON chatmessage (intent);

COMMIT;
